steps.expression:
((inspection) => { if (!inspection || !inspection.ok) return { ok: false, reason: 'inspection failed' }; let report = '
【节点入参探查报告】
'; report += `字段总数: ${inspection.fields.length}
`; report += `必填字段: ${inspection.requiredFields.length}
`; report += `下拉选择: ${inspection.selectFields.length}
`; report += `输入框: ${inspection.inputFields.length}

`; report += '【所有字段详情】
'; for (const f of inspection.fields) { report += `  ${f.required ? '*' : ' '} ${f.label.padEnd(15)} [${f.type}] 当前值: ${f.currentValue}
`; } report += '
【必填字段列表】
'; for (const f of inspection.requiredFields) { report += `  * ${f.label}: ${f.currentValue}
`; } report += '
【是否有入参配置区域】
'; report += `  ${inspection.hasInputParams ? '✅ 是' : '❌ 否'}
`; return { ok: true, report, data: inspection }; })
